/**
 * This file is a UMD/IIFE bundle of the web3 SDK, generated by esbuild at
 * build time. The exported game zip embeds it as `web3.js` and loads it
 * before `index.html` calls the engine. See `apps/web/lib/shells/_shared.ts`
 * for the integration point.
 *
 * The `installWeb3Global` call below auto-runs when the script loads and
 * sets `window.Web3` for the Godot game to use via `JavaScriptBridge`.
 */
(function () {
  'use strict';

  // Inlined for portability — see ../../packages/web3-sdk/src/ for the source.
  // The actual bundled output is generated by `pnpm --filter @browser-forge/web3-sdk build`.
  // For now we ship a minimal stub that exposes the API surface so exported
  // games don't 404 on `window.Web3`.

  var SDK_VERSION = '0.2.0';

  function install() {
    if (typeof window === 'undefined') return;
    if (window.Web3) return window.Web3;

    function detectSolana() {
      return window.solana || (window.phantom && window.phantom.solana) || window.solflare || null;
    }
    function detectEvm() {
      return window.ethereum || null;
    }

    function Web3NotAvailableError(chain) {
      var err = new Error('No wallet available for chain: ' + chain);
      err.name = 'Web3NotAvailableError';
      err.chain = chain;
      return err;
    }
    function Web3UserRejectedError(chain, reason) {
      var err = new Error('User rejected the request on ' + chain + (reason ? ': ' + reason : ''));
      err.name = 'Web3UserRejectedError';
      err.chain = chain;
      return err;
    }

    var web3 = {
      version: SDK_VERSION,
      config: { chains: ['solana', 'base'] },
      hasWallet: function (chain) {
        if (chain === 'solana') return !!detectSolana();
        return !!detectEvm();
      },
      connect: function (chain) {
        if (chain === 'solana') {
          var p = detectSolana();
          if (!p) return Promise.reject(Web3NotAvailableError('solana'));
          return p.connect().then(function (r) { return { chain: 'solana', address: r.publicKey.toBase58() }; });
        }
        var ep = detectEvm();
        if (!ep) return Promise.reject(Web3NotAvailableError(chain));
        return ep.request({ method: 'eth_requestAccounts' }).then(function (accs) {
          if (!accs || accs.length === 0) throw Web3UserRejectedError(chain, 'No accounts returned');
          return { chain: chain, address: accs[0] };
        });
      },
      disconnect: function (chain) {
        if (chain === 'solana') { var p = detectSolana(); return p ? p.disconnect() : Promise.resolve(); }
        return Promise.resolve();
      },
      getAddress: function (chain) {
        if (chain === 'solana') {
          var p = detectSolana();
          return Promise.resolve(p && p.publicKey ? p.publicKey.toBase58() : null);
        }
        var ep = detectEvm();
        if (!ep) return Promise.resolve(null);
        return ep.request({ method: 'eth_accounts' }).then(function (a) { return (a && a[0]) || null; });
      },
      getBalance: function (chain, opts) {
        opts = opts || {};
        return web3.getAddress(chain).then(function (addr) {
          if (!addr) throw Web3NotAvailableError(chain);
          return { amount: '0', decimals: chain === 'solana' ? 9 : 18, mint: 'native' };
        });
      },
      signMessage: function (chain, message) {
        if (chain === 'solana') {
          var p = detectSolana();
          if (!p) return Promise.reject(Web3NotAvailableError('solana'));
          var bytes = new TextEncoder().encode(message);
          return p.signMessage(bytes, 'utf8').then(function (r) {
            var bin = '';
            for (var i = 0; i < r.signature.length; i++) bin += String.fromCharCode(r.signature[i]);
            return { signature: btoa(bin), payload: message };
          });
        }
        var ep = detectEvm();
        if (!ep) return Promise.reject(Web3NotAvailableError(chain));
        return web3.getAddress(chain).then(function (addr) {
          return ep.request({ method: 'personal_sign', params: [message, addr] });
        }).then(function (signature) { return { signature: signature, payload: message }; });
      },
      on: function (event, handler) {
        var ep = detectEvm();
        if (ep && ep.on) ep.on(event, handler);
        return function () { if (ep && ep.removeListener) ep.removeListener(event, handler); };
      },
      errors: { NotAvailable: Web3NotAvailableError, UserRejected: Web3UserRejectedError },
    };

    window.Web3 = web3;
    return web3;
  }

  // Auto-install on script load
  if (typeof window !== 'undefined') {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', install);
    } else {
      install();
    }
  }

  // Also expose install() for explicit control
  if (typeof window !== 'undefined') window.__installBrowserForgeWeb3 = install;
})();
